begin;
create extension if not exists pgtap with schema extensions;
select plan(17);
select has_table('public','business_settings','versioned business settings exist');
insert into public.organizations(id,name,slug) values('a0000000-0000-0000-0000-000000000008','Settings test','settings-test-008');
insert into auth.users(id) values('b0000000-0000-4000-8000-000000000081'),('b0000000-0000-4000-8000-000000000082');
insert into public.staff_profiles(user_id,organization_id,role) values('b0000000-0000-4000-8000-000000000081','a0000000-0000-0000-0000-000000000008','manager'),('b0000000-0000-4000-8000-000000000082','a0000000-0000-0000-0000-000000000008','staff');
create temporary table input as select '{"brandName":"Local fixture","brandVoice":"Lịch sự","allowedTopics":[],"forbiddenTopics":[],"timezone":"Asia/Ho_Chi_Minh","goalSelection":"auto","managerGoal":"","timingMode":"constrained","dailyCap":1,"windows":[{"start":"09:00","end":"17:00"}],"objective":"mixed"}'::jsonb settings;
select ok(not has_table_privilege('authenticated','public.business_settings','SELECT'),'no browser access');
select ok(not has_table_privilege('service_role','public.business_settings','UPDATE'),'service writes only through atomic RPC');
select throws_ok($$select public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000082',0,gen_random_uuid(),settings) from input$$,'42501','settings_forbidden','staff save denied');
select is((public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000081',0,'c0000000-0000-4000-8000-000000000081',settings)->>'revision')::int,1,'initial save creates revision one') from input;
select is((select count(*) from public.audit_events where idempotency_key='c0000000-0000-4000-8000-000000000081'),1::bigint,'save writes one audit event');
select is((public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000081',0,'c0000000-0000-4000-8000-000000000081',settings)->>'revision')::int,1,'identical retry returns original result') from input;
select throws_ok($$select public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000081',0,'c0000000-0000-4000-8000-000000000081',settings||'{"dailyCap":2}'::jsonb) from input$$,'40001','settings_version_conflict','changed idempotent payload rejected');
select throws_ok($$select public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000081',0,gen_random_uuid(),settings) from input$$,'40001','settings_version_conflict','stale version rejected');
select is((public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000081',1,'c0000000-0000-4000-8000-000000000082',settings||'{"dailyCap":2}'::jsonb)->>'revision')::int,2,'latest version saves') from input;
select is((select settings->>'dailyCap' from public.business_settings where organization_id='a0000000-0000-0000-0000-000000000008'),'2','next read sees updated setting');
select throws_ok($$select public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000081',2,gen_random_uuid(),settings||'{"timezone":"Invalid/Zone"}'::jsonb) from input$$,'22023','invalid_settings','DB rejects invalid timezone');
select ok(not public.valid_business_settings(settings||'{"objective":null}'::jsonb),'DB rejects JSON null mode') from input;
update public.staff_profiles set active=false where user_id='b0000000-0000-4000-8000-000000000081';
select throws_ok($$select public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000081',2,gen_random_uuid(),settings) from input$$,'42501','settings_forbidden','disabled manager rejected inside transaction');
update public.staff_profiles set active=true where user_id='b0000000-0000-4000-8000-000000000081';
create function pg_temp.reject_settings_audit() returns trigger language plpgsql as $$begin raise exception 'fixture_audit_failure'; end$$;
create trigger settings_audit_fixture before insert on public.audit_events for each row execute function pg_temp.reject_settings_audit();
select throws_ok($$select public.save_business_settings('a0000000-0000-0000-0000-000000000008','b0000000-0000-4000-8000-000000000081',2,'c0000000-0000-4000-8000-000000000083',settings) from input$$,'P0001','fixture_audit_failure','audit failure rolls back whole save');
select is((select revision from public.business_settings where organization_id='a0000000-0000-0000-0000-000000000008'),2,'revision unchanged after audit failure');
select is((select count(*) from public.business_settings_requests where request_id='c0000000-0000-4000-8000-000000000083'),0::bigint,'failed transaction leaves no idempotency receipt');
select * from finish();
rollback;
